-- ============================================================
-- 速卖通运营定价系统 · 本地部署数据库初始化脚本
-- 生成时间: 2026-09-27（数据快照：运费标准 14199 行 / 模板 3 条 / 参数 1 条）
--
-- 用法（在全新 PostgreSQL >= 14 数据库上执行一次）:
--   psql -d <数据库名> -f database/init.sql
--
-- 说明:
--   - 包含平台自定义复合类型 user_profile / file_attachment、
--     三张业务表结构、索引与注释、以及全量数据
--   - 仅适配本地部署: 未包含平台 RLS 策略与 workspace schema
--   - 脚本非幂等: 重复执行会因主键冲突报错, 请在全新库上执行
-- ============================================================

-- 平台自定义复合类型（应用 ORM 写入审计列时依赖 user_profile 类型）
DO $$ BEGIN
  CREATE TYPE user_profile AS (user_id character varying);
EXCEPTION
  WHEN duplicate_object THEN NULL;
END $$;

DO $$ BEGIN
  CREATE TYPE file_attachment AS (bucket_id text, file_path text);
EXCEPTION
  WHEN duplicate_object THEN NULL;
END $$;

-- 运费标准表
CREATE TABLE IF NOT EXISTS ae_shipping_rate (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  line_name character varying(100) NOT NULL,
  line_category character varying(50) NOT NULL DEFAULT '经济类物流',
  goods_type character varying(20) NOT NULL DEFAULT '普货',
  country_zh character varying(100) NOT NULL,
  country_en character varying(150) NOT NULL,
  country_code character varying(10) NOT NULL,
  currency character varying(10) NOT NULL DEFAULT 'RMB',
  weight_min_g integer NOT NULL DEFAULT 1,
  weight_max_g integer NOT NULL,
  fee_per_kg numeric(12,4) NULL,
  registration_fee numeric(12,4) NULL,
  min_charge_g integer NOT NULL DEFAULT 1,
  calc_mode character varying(20) NOT NULL DEFAULT 'per_gram',
  first_weight_fee numeric(12,4) NULL,
  additional_fee_per_500g numeric(12,4) NULL,
  tier_label character varying(100) NULL,
  volume_divisor integer NOT NULL DEFAULT 5000,
  _created_at timestamp(3) with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  _created_by user_profile NULL DEFAULT
    CASE
      WHEN (current_setting('app.user_id'::text, true) = ''::text) THEN NULL::user_profile
      ELSE (concat('(', current_setting('app.user_id'::text, true), ')'))::user_profile
    END,
  _updated_at timestamp(3) with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  _updated_by user_profile NULL DEFAULT
    CASE
      WHEN (current_setting('app.user_id'::text, true) = ''::text) THEN NULL::user_profile
      ELSE (concat('(', current_setting('app.user_id'::text, true), ')'))::user_profile
    END,
  CONSTRAINT ae_shipping_rate_pkey PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS idx_ae_shipping_rate_lookup
  ON ae_shipping_rate (line_name, country_code, goods_type);

COMMENT ON COLUMN ae_shipping_rate.goods_type IS '普货|非普货(含电/非液体化妆品)|大包';
COMMENT ON COLUMN ae_shipping_rate.calc_mode IS 'per_gram=按克计费(费用=fee_per_kg*计费克重/1000+registration_fee); first_additional=首重续重(费用=first_weight_fee+ceil((克重-500)/500)*additional_fee_per_500g)';

-- 运费模板表
CREATE TABLE IF NOT EXISTS ae_shipping_template (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  name character varying(100) NOT NULL,
  remark character varying(500) NULL,
  group_list jsonb NOT NULL DEFAULT '[]'::jsonb,
  _created_at timestamp(3) with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  _created_by user_profile NULL DEFAULT
    CASE
      WHEN (current_setting('app.user_id'::text, true) = ''::text) THEN NULL::user_profile
      ELSE (concat('(', current_setting('app.user_id'::text, true), ')'))::user_profile
    END,
  _updated_at timestamp(3) with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  _updated_by user_profile NULL DEFAULT
    CASE
      WHEN (current_setting('app.user_id'::text, true) = ''::text) THEN NULL::user_profile
      ELSE (concat('(', current_setting('app.user_id'::text, true), ')'))::user_profile
    END,
  CONSTRAINT ae_shipping_template_pkey PRIMARY KEY (id)
);

COMMENT ON COLUMN ae_shipping_template.group_list IS '@type { lineName: string; goodsType: string; chargeMode: string; discountPercent?: number; countries: { countryCode: string; countryZh: string }[] }[]';

-- 定价参数表（单行）
CREATE TABLE IF NOT EXISTS ae_pricing_setting (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  commission_rate numeric(6,4) NOT NULL DEFAULT 0.08,
  exchange_rate numeric(10,4) NOT NULL DEFAULT 7.2,
  loss_rate numeric(6,4) NOT NULL DEFAULT 0,
  default_profit_rate numeric(6,4) NOT NULL DEFAULT 0.2,
  _created_at timestamp(3) with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  _created_by user_profile NULL DEFAULT
    CASE
      WHEN (current_setting('app.user_id'::text, true) = ''::text) THEN NULL::user_profile
      ELSE (concat('(', current_setting('app.user_id'::text, true), ')'))::user_profile
    END,
  _updated_at timestamp(3) with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  _updated_by user_profile NULL DEFAULT
    CASE
      WHEN (current_setting('app.user_id'::text, true) = ''::text) THEN NULL::user_profile
      ELSE (concat('(', current_setting('app.user_id'::text, true), ')'))::user_profile
    END,
  CONSTRAINT ae_pricing_setting_pkey PRIMARY KEY (id)
);

